<?php
declare(strict_types=1);
$root=dirname(__DIR__);require $root.'/app/Memory/MarkdownJsonMemory.php';
$base=sys_get_temp_dir().'/dcp-memory-'.bin2hex(random_bytes(5));
try{$m=new MarkdownJsonMemory($base);$saved=$m->remember(['title'=>'DCP Q012 decision','content'=>'The coordinator stores provider proposals and requires approval before side effects.','level'=>'project','project'=>'DCP','agent'=>'any','tags'=>['Q012','approval']]);if(!is_file($base.'/memory/index.json'))throw new RuntimeException('JSON memory index missing.');$bootstrap=$m->bootstrap('DCP');if(count($bootstrap['items'])!==1)throw new RuntimeException('Hierarchical bootstrap did not return the project memory.');$recall=$m->recall('coordinator approval','DCP');if(count($recall)!==1)throw new RuntimeException('Keyword recall did not return the expected memory.');$read=$m->read($saved['id']);if(!str_contains($read['content'],'side effects'))throw new RuntimeException('Markdown read did not return stored content.');$secret=$m->remember(['title'=>'Credential redaction','content'=>'API_KEY=abc1234567890 and Bearer abcdefghijklmnopqrstuvwxyz_123456','level'=>'global','project'=>'global']);$secretRead=$m->read($secret['id']);if(str_contains($secretRead['content'],'abc1234567890')||str_contains($secretRead['content'],'abcdefghijklmnopqrstuvwxyz_123456'))throw new RuntimeException('Secret redaction failed.');$retired=$m->retire($saved['id'],'superseded by a newer reviewed memory');if(($retired['status']??'')!=='retired'||!($retired['history_preserved']??false))throw new RuntimeException('Soft retirement did not preserve history.');$after=$m->bootstrap('DCP');if(in_array($saved['id'],array_column($after['items'],'id'),true))throw new RuntimeException('Retired memory was still served by bootstrap.');echo "DCP_MEMORY_MD_JSON_PASS\n";}finally{if(is_dir($base)){ $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($base,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f){$f->isDir()?rmdir($f->getPathname()):unlink($f->getPathname());}rmdir($base);}}
